import { useContext } from 'react';
import { TooltipContext } from './TooltipContext';

const Button = ({ children, tooltip }) => {
  const { openTooltip } = useContext(TooltipContext);

  return (
    <button onClick={() => openTooltip(tooltip)}>
      {children}
    </button>
  );
};

export default Button;
```

```jsx
