function getElapsedTime(postDate: Date): string {
    const now = new Date();
    const timeDiff = now.getTime() - postDate.getTime();
    const days = Math.floor(timeDiff / (1000 * 60 * 60 * 24));
    const hours = Math.floor((timeDiff % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60));
