export default class CsvDownloadRoute extends Route {
  model() {
    return {
      csvData: 'data,here,for,example',
      filename: 'example.csv'
    };
  }
}
```
Next, we'll create a new service to handle the CSV download using a web worker:
```javascript
// services/csv-download.js
import Service from '@ember/service';
import { Worker } from 'web-workers';

export default class CsvDownloadService extends Service {
  csvData = null;
  filename = null;
  worker = null;

  init() {
    super.init(...arguments);
    this.worker = new Worker('workers/csv-download-worker.js');
  }

  downloadCsv() {
    this.worker.postMessage({
      csvData: this.csvData,
      filename: this.filename
    });
  }
}
```
Now, let's create the web worker script that will handle the CSV download:
```javascript
// workers/csv-download-worker.js
import { Worker } from 'web-workers';

self.onmessage = (event) => {
  const { csvData, filename } = event.data;
  const blob = new Blob([csvData], { type: 'text/csv' });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
};
```
Finally, let's update our route to use the CSV download service:
```javascript
// routes/csv-download.js
import Route from '@ember/routing/route';
import CsvDownloadService from 'services/csv-download';

export default class CsvDownloadRoute extends Route {
  csvDownloadService = CsvDownloadService;

  model() {
    return {
      csvData: 'data,here,for,example',
      filename: 'example.csv'
    };
  }

  afterModel() {
    this.csvDownloadService.downloadCsv();
  }
}
```
This will create a new web worker that will handle the CSV download, allowing our application to continue running without blocking the main thread.

